const el=s=>document.querySelector(s), money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(Number(n||0));
let me=null,stages=[],perms=new Set(),current='dashboard';
const api=async(url,opt={})=>{const r=await fetch(url,{headers:{'content-type':'application/json',...(opt.headers||{})},...opt});const j=await r.json().catch(()=>({}));if(!r.ok)throw new Error(j.error||`HTTP ${r.status}`);return j};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
const can=p=>perms.has(p);
function renderLogin(){el('#app').innerHTML=`<div class="login"><form class="login-card" id="login"><img src="/brand-logo.png" class="login-logo"><h1>Owner Tracker <span>V10</span></h1><p class="muted">Owner, manager, service writer, technician and parts access.</p><input name="username" autocomplete="username" placeholder="Employee username" required><input name="password" type="password" autocomplete="current-password" placeholder="Password or employee PIN" required><button class="btn primary">Sign in</button></form></div>`;el('#login').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));try{await api('/api/login',{method:'POST',body:JSON.stringify(f)});location.reload()}catch(x){alert(x.message)}}}
function shell(){const nav=[['dashboard','Dashboard'],['mywork','My Work'],['workorders','Work Orders']];if(can('edit_job'))nav.push(['customers','Customers'],['vehicles','Vehicles'],['newwo','+ New WO'],['payments','Payments'],['billing','Invoice / DocuSign'],['hardware','POS Hardware']);if(can('parts'))nav.push(['procurement','Parts']);if(can('read'))nav.push(['shopops','Shop Operations']);if(can('users'))nav.push(['employees','Employees']);el('#app').innerHTML=`<div class="app"><header class="topbar"><div class="brand"><img class="header-logo" src="/brand-logo.png" alt="AZ Jet Ski + Powersports"> Owner <span>Tracker V11</span></div><div class="top-actions"><span class="user-chip">${esc(me.user.displayName)} • ${esc(me.user.role.replace('_',' '))}</span><button class="btn" id="logout">Sign out</button></div></header><main class="container"><nav class="nav">${nav.map(n=>`<button data-go="${n[0]}">${n[1]}</button>`).join('')}</nav><div id="view"></div></main></div>`;document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));el('#logout').onclick=async()=>{await api('/api/logout',{method:'POST',body:'{}'});location.reload()}}
function navActive(){document.querySelectorAll('[data-go]').forEach(b=>b.classList.toggle('active',b.dataset.go===current))}
async function go(name){if(name==='billing'){location.href='/billing.html';return;}if(name==='shopops'){location.href='/shop-ops.html';return;}current=name;navActive();el('#view').innerHTML='<div class="empty">Loading…</div>';try{if(name==='dashboard')await dashboard();if(name==='mywork')await myWork();if(name==='workorders')await workorders();if(name==='procurement')await procurement();if(name==='employees')await employees();if(name==='customers')await posCustomers();if(name==='vehicles')await posVehicles();if(name==='newwo')await createPOSWorkOrder();if(name==='payments')await posPayments();if(name==='hardware')await posHardware()}catch(e){el('#view').innerHTML=`<div class="card"><h2>Unable to load</h2><p>${esc(e.message)}</p></div>`}}
function table(rows){return `<div class="line-table"><table><thead><tr><th>WO</th><th>Customer / Unit</th><th>Stage</th><th>Assigned</th><th>Next action</th><th>Total</th></tr></thead><tbody>${rows.map(w=>`<tr class="click" data-id="${w.id}"><td><strong>${esc(w.ref_number||w.id)}</strong></td><td>${esc(w.customer_name||'')}<div class="muted">${esc(w.unit_label||[w.year,w.make,w.model].filter(Boolean).join(' '))}</div></td><td><span class="badge">${esc(w.stage)}</span></td><td>${esc(w.assigned_name||w.tech||'Unassigned')}</td><td>${esc(w.next_action||'—')}</td><td>${money(w.estimate_total)}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">No work orders</td></tr>'}</tbody></table></div>`}
function bindRows(){document.querySelectorAll('tr[data-id]').forEach(r=>r.onclick=()=>detail(r.dataset.id))}
async function dashboard(){const d=await api('/api/dashboard'),s=d.summary;el('#view').innerHTML=`<div class="page-title"><div><h1>Shop Dashboard</h1><p class="muted">What needs attention right now.</p></div></div><div class="grid metrics"><div class="metric"><div class="muted">Open Jobs</div><div class="value">${s.open_jobs}</div></div><div class="metric"><div class="muted">Pipeline</div><div class="value">${money(s.pipeline)}</div></div><div class="metric"><div class="muted">Unpaid</div><div class="value">${money(s.unpaid)}</div></div><div class="metric"><div class="muted">Awaiting Approval</div><div class="value">${s.approvals||0}</div></div><div class="metric alert"><div class="muted">Parts Missing</div><div class="value">${s.parts_missing||0}</div></div><div class="metric"><div class="muted">Orders Ready</div><div class="value">${s.orders_ready||0}</div></div></div><div class="grid two"><div class="card"><h2>Pipeline</h2><div class="pipeline">${d.pipeline.map(x=>`<div class="pipe-row"><span>${esc(x.stage)}</span><strong>${x.count}</strong><span>${money(x.total)}</span></div>`).join('')}</div></div><div class="card"><h2>Recently Active</h2>${table(d.recent)}</div></div>`;bindRows()}
async function myWork(){const d=await api('/api/my-work');el('#view').innerHTML=`<div class="page-title"><div><h1>My Work</h1><p class="muted">Mobile-first queue for the shop floor.</p></div></div><div class="job-cards">${d.workOrders.map(w=>`<button class="job-card" data-card="${w.id}"><div><strong>WO ${esc(w.ref_number||w.id)}</strong> <span class="priority ${esc(w.priority||'normal')}">${esc(w.priority||'normal')}</span></div><h3>${esc(w.unit_label||[w.year,w.make,w.model].filter(Boolean).join(' ')||w.customer_name)}</h3><div class="muted">${esc(w.customer_name||'')} • ${esc(w.stage)}</div><div class="next-action">${esc(w.next_action||'Open job')}</div></button>`).join('')||'<div class="empty">No jobs assigned.</div>'}</div>`;document.querySelectorAll('[data-card]').forEach(x=>x.onclick=()=>detail(x.dataset.card))}
async function workorders(){const d=await api('/api/work-orders');el('#view').innerHTML=`<div class="page-title"><div><h1>Work Orders</h1><p class="muted">Create, edit, track and complete work orders — no QuickBooks required.</p></div></div><div class="toolbar"><input id="search" placeholder="Search work order, customer, phone, unit"><select id="stage"><option value="">All stages</option>${stages.map(s=>`<option>${esc(s)}</option>`).join('')}</select></div><div class="card" id="list">${table(d.workOrders)}</div>`;bindRows();let t;el('#search').oninput=()=>{clearTimeout(t);t=setTimeout(load,250)};el('#stage').onchange=load;async function load(){const q=encodeURIComponent(el('#search').value),s=encodeURIComponent(el('#stage').value);const x=await api(`/api/work-orders?q=${q}&stage=${s}`);el('#list').innerHTML=table(x.workOrders);bindRows()}}
async function getEmployees(){if(!can('assign_job'))return[];try{return (await api('/api/staff')).users.filter(x=>x.active)}catch{return[]}}
async function compressImage(file){return new Promise((resolve,reject)=>{const img=new Image(),url=URL.createObjectURL(file);img.onload=()=>{try{const max=1800,scale=Math.min(1,max/Math.max(img.width,img.height)),c=document.createElement('canvas');c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);c.getContext('2d').drawImage(img,0,0,c.width,c.height);URL.revokeObjectURL(url);resolve({filename:file.name.replace(/\.[^.]+$/,'.jpg'),mimeType:'image/jpeg',dataBase64:c.toDataURL('image/jpeg',.82)})}catch(e){reject(e)}};img.onerror=()=>reject(new Error('Could not read image'));img.src=url})}
async function uploadFiles(id,files,{scope='progress',caption='',customerVisible=true}={}){const ids=[];for(const file of [...files]){const x=await compressImage(file),r=await api(`/api/work-orders/${id}/media`,{method:'POST',body:JSON.stringify({...x,scope,caption,customerVisible})});ids.push(r.mediaId)}return ids}
function mediaGrid(media){return `<div class="photo-grid">${media.map(m=>`<figure><img src="/api/media/${m.id}" alt="${esc(m.caption||'Work photo')}"><figcaption>${esc(m.caption||m.scope)}${m.customer_visible?' • Customer visible':' • Internal'}</figcaption></figure>`).join('')||'<div class="empty">No photos yet.</div>'}</div>`}
function partsTable(parts,id){return `<div class="line-table"><table><thead><tr><th>Part</th><th>Need</th><th>Ordered</th><th>Received</th><th>Status</th><th>Vendor</th><th>Parts ETA</th></tr></thead><tbody>${parts.map(p=>`<tr><td><strong>${esc(p.item_ref||'')}</strong><div class="muted">${esc(p.description)}</div></td><td>${p.qty_needed}</td><td>${p.qty_ordered}</td><td>${p.qty_received}</td><td><span class="badge">${esc(p.status)}</span></td><td>${esc(p.preferred_vendor_name||'Not sourced')}</td><td>${esc(p.offers?.find(o=>o.vendor_id===p.preferred_vendor_id)?.eta_text||p.offers?.[0]?.eta_text||'Not available')}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">No parts requested.</td></tr>'}</tbody></table></div>${can('parts')?`<button class="btn primary" id="buildCarts">Build / Update Supplier Carts</button>`:''}`}
async function detail(id){const [d,employeesList]=await Promise.all([api(`/api/work-orders/${id}`),getEmployees()]),w=d.workOrder;current='workorders';navActive();const assignOptions=`<option value="">Unassigned</option>${employeesList.map(x=>`<option value="${x.id}" ${Number(w.assigned_user_id)===Number(x.id)?'selected':''}>${esc(x.displayName)} — ${esc(x.role)}</option>`).join('')}`;el('#view').innerHTML=`<div class="detail-title"><div><button class="btn" id="back">← Work Orders</button><h1>WO ${esc(w.ref_number||w.id)}</h1><div class="muted">${esc(w.customer_name)} • ${esc(w.unit_label||[w.year,w.make,w.model].filter(Boolean).join(' '))}</div></div><div class="actions">${can('updates')?'<button class="btn" id="customerLink">Customer Link</button>':''}${can('approval')?'<button class="btn primary" id="approval">Send Approval</button>':''}${can('ready')?'<button class="btn" id="ready">Ready for Pickup</button>':''}</div></div><div class="split"><div class="card"><h2>Workflow</h2><form id="edit"><div class="form-grid"><div class="field"><label>Stage</label><select name="stage" ${can('edit_job')?'':'disabled'}>${stages.map(s=>`<option ${s===w.stage?'selected':''}>${esc(s)}</option>`).join('')}</select></div><div class="field"><label>Assigned employee</label><select name="assigned_user_id" ${can('assign_job')?'':'disabled'}>${assignOptions}</select></div><div class="field"><label>Priority</label><select name="priority" ${can('edit_job')?'':'disabled'}>${['normal','high','urgent'].map(x=>`<option ${x===w.priority?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Next action due</label><input name="next_action_due" type="date" value="${esc((w.next_action_due||'').slice(0,10))}" ${can('edit_job')?'':'disabled'}></div></div><div class="field"><label>Next action</label><input name="next_action" value="${esc(w.next_action||'')}" ${can('edit_job')?'':'disabled'}></div><div class="field"><label>Complaint</label><textarea name="complaint" ${can('edit_job')?'':'disabled'}>${esc(w.complaint||'')}</textarea></div><div class="field"><label>Authorized Work</label><textarea name="authorized_work" ${can('edit_job')?'':'disabled'}>${esc(w.authorized_work||'')}</textarea></div>${can('edit_job')?'<button class="btn primary">Save Workflow</button>':''}</form></div><div class="card"><h2>Financials</h2><div class="pipe-row"><span>Total</span><strong>${money(w.estimate_total)}</strong></div><div class="pipe-row"><span>Parts</span><strong>${money(w.parts_total)}</strong></div><div class="pipe-row"><span>Labor</span><strong>${money(w.labor_total)}</strong></div><div class="pipe-row"><span>Paid</span><strong>${money(w.paid_total)}</strong></div><div class="pipe-row"><span>Balance</span><strong>${money(w.balance)}</strong></div><p class="muted">QB status: ${esc(w.qb_status||'—')}<br>Opened: ${esc(w.date_opened||'—')}<br>Last POS change: ${esc(w.time_modified||w.updated_at)}</p></div></div>
    ${can('updates')?`<div class="card section"><h2>Customer Update + Photos</h2><p class="muted">Technicians can photograph findings or progress from a phone. Customer-visible photos follow the job into the status page and can be attached to an approval.</p><form id="updateForm"><div class="form-grid"><div class="field"><label>Update title</label><input name="title" placeholder="Diagnosis complete"></div><div class="field"><label>Stage after update</label><select name="stage">${stages.map(s=>`<option ${s===w.stage?'selected':''}>${esc(s)}</option>`).join('')}</select></div></div><div class="field"><label>Customer message</label><textarea name="body" placeholder="We completed testing and found…"></textarea></div><div class="field"><label>Photo caption</label><input name="caption" placeholder="Worn drive belt / damaged wear ring / progress photo"></div><div class="field"><label>Take or upload photos</label><input id="photos" type="file" accept="image/*" capture="environment" multiple></div><label class="check-row"><input type="checkbox" name="customerVisible" checked> Customer can see this update and its photos</label><label class="check-row"><input type="checkbox" name="notifyCustomer"> Notify customer now</label><button class="btn primary">Post Update</button></form></div>`:''}
    <div class="card section"><div class="section-head"><h2>Photos</h2></div>${mediaGrid(w.media)}</div>
    <div class="card section"><h2>Customer Timeline</h2><div class="timeline">${w.updates.map(u=>`<div class="timeline-item"><strong>${esc(u.title||u.stage||'Update')}</strong> <span class="badge">${u.customer_visible?'Customer':'Internal'}</span><div class="muted">${esc(u.author_name)} • ${esc(u.created_at)} • ${esc(u.stage||'')}</div><div>${esc(u.body||'')}</div></div>`).join('')||'<div class="empty">No progress updates yet.</div>'}</div></div>
    <div class="card section"><h2>Parts Procurement</h2>${partsTable(w.parts,id)}</div>
    <div class="card section"><h2>POS Parts / Labor Lines</h2><div class="line-table">${w.lines.length?`<table><thead><tr><th>Type</th><th>Item</th><th>Description</th><th>Qty</th><th>Amount</th></tr></thead><tbody>${w.lines.map(l=>`<tr><td>${esc(l.line_type||'')}</td><td>${esc(l.item_ref||'')}</td><td>${esc(l.description||'')}</td><td>${l.qty}</td><td>${money(l.amount)}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">No lines imported</div>'}</div></div>
    <div class="grid two"><div class="card"><h2>Internal Notes</h2>${can('notes')?'<form id="note"><textarea name="body" placeholder="Internal note — not shown to customer"></textarea><button class="btn">Add Note</button></form>':''}<div class="timeline">${w.notes.map(n=>`<div class="timeline-item"><strong>${esc(n.author)}</strong> <span class="muted">${esc(n.created_at)}</span><div>${esc(n.body)}</div></div>`).join('')||'<div class="empty">No notes</div>'}</div></div><div class="card"><h2>Audit History</h2><div class="timeline">${w.audit.slice(0,30).map(a=>`<div class="timeline-item"><strong>${esc(a.action)}</strong><div class="muted">${esc(a.actor)} • ${esc(a.created_at)}</div></div>`).join('')}</div></div></div>`;
  await attachPOSActions(id,w);if(can('edit_job')){const payButton=document.createElement('button');payButton.className='btn primary';payButton.textContent='Payments / Deposits';el('.detail-title .actions').append(payButton);payButton.onclick=()=>workOrderPayments(id);}el('#back').onclick=()=>go('workorders');
  if(can('edit_job'))el('#edit').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));await api(`/api/work-orders/${id}`,{method:'PATCH',body:JSON.stringify(f)});await detail(id)};
  if(can('notes'))el('#note').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));await api(`/api/work-orders/${id}/notes`,{method:'POST',body:JSON.stringify(f)});await detail(id)};
  if(can('updates'))el('#updateForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),files=el('#photos').files;const visible=f.get('customerVisible')==='on';const btn=e.target.querySelector('button');btn.disabled=true;btn.textContent='Posting…';try{const mediaIds=files.length?await uploadFiles(id,files,{scope:'progress',caption:f.get('caption'),customerVisible:visible}):[];const r=await api(`/api/work-orders/${id}/updates`,{method:'POST',body:JSON.stringify({title:f.get('title'),body:f.get('body'),stage:f.get('stage'),customerVisible:visible,notifyCustomer:f.get('notifyCustomer')==='on',mediaIds})});if(r.portalUrl)prompt('Customer update sent. Status link:',r.portalUrl);await detail(id)}catch(x){alert(x.message);btn.disabled=false;btn.textContent='Post Update'}};
  if(can('approval'))el('#approval').onclick=async()=>{const desc=prompt('Authorized work description:',w.authorized_work||w.complaint||'');if(desc===null)return;const choices=w.media.filter(m=>m.customer_visible).map(m=>m.id);const include=choices.length&&confirm(`Attach the ${choices.length} customer-visible photo(s) on this work order to the approval?`)?choices:[];try{const r=await api(`/api/work-orders/${id}/request-approval`,{method:'POST',body:JSON.stringify({authorizedDescription:desc,mediaIds:include})});prompt('Approval sent. Customer approval link:',r.approvalUrl);await detail(id)}catch(x){alert(x.message)}};
  if(can('ready'))el('#ready').onclick=async()=>{if(!confirm('Mark Ready and trigger pickup notification?'))return;const r=await api(`/api/work-orders/${id}/ready`,{method:'POST',body:'{}'});if(r.portalUrl)prompt('Ready notification triggered. Customer status link:',r.portalUrl);await detail(id)};
  if(can('updates'))el('#customerLink').onclick=async()=>{const r=await api(`/api/work-orders/${id}/customer-link`,{method:'POST',body:'{}'});prompt('Customer status link:',r.portalUrl)};
  if(can('parts')&&el('#buildCarts'))el('#buildCarts').onclick=async()=>{const r=await api(`/api/work-orders/${id}/parts/build-carts`,{method:'POST',body:'{}'});if(r.missing.length)alert(`${r.missing.length} part(s) still have no supplier match. They are flagged in Procurement.`);else alert('Supplier carts updated.');await procurement()};
}
async function procurement(){const d=await api('/api/procurement');current='procurement';navActive();el('#view').innerHTML=`<div class="page-title"><div><h1>Parts Command Center</h1><p class="muted">Parts needed → source → threshold → verify → desktop queue → track / receive.</p></div><div class="actions"><button class="btn" id="refreshSuppliers">Check Suppliers</button><button class="btn" id="refreshOrders">Refresh Order Status</button><button class="btn primary" id="buildAll">Build All Carts</button><span class="badge big">Live ordering: ${d.liveVendorOrdering?'ENABLED':'SAFE / OFF'}</span></div></div><div class="grid vendor-grid">${d.vendors.map(v=>`<div class="card"><strong>${esc(v.name)}</strong><div class="muted">Threshold ${money(v.order_threshold)} • Manual verification required</div><div class="muted">${esc(v.integration_mode)}</div></div>`).join('')}</div><div class="card section"><h2>Missing Supplier Matches <span class="badge">${d.missing.length}</span></h2>${d.missing.length?`<div class="line-table"><table><thead><tr><th>WO</th><th>Part</th><th>Qty</th><th>Action</th></tr></thead><tbody>${d.missing.map(x=>`<tr><td>${esc(x.ref_number)}</td><td>${esc(x.item_ref||'')}<div class="muted">${esc(x.description)}</div></td><td>${x.qty_needed}</td><td><button class="btn" data-source="${x.id}">Add supplier offer</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="success">Every active required part has a supplier offer or cart.</div>'}</div><div class="card section"><h2>Supplier Carts / Orders</h2>${d.carts.map(c=>`<div class="order-card"><div class="order-head"><div><strong>${esc(c.vendor_name)} — Cart #${c.id}</strong><div class="muted">${esc(c.status)} • Threshold ${money(c.threshold_snapshot)}</div></div><div><strong>${money(c.total)}</strong></div></div><div class="line-table"><table><tbody>${c.lines.map(l=>`<tr><td>WO ${esc(l.ref_number)}<div class="muted">${esc(l.unit_label||'')}</div></td><td>${esc(l.vendor_sku||'')}<div class="muted">Requested ${esc(l.requested_item_ref||'')}</div></td><td>${esc(l.description)}</td><td>x ${l.qty}</td><td>${money(l.unit_cost)}</td><td>ETA: ${esc(l.eta_text||c.eta_text||'Not provided')}</td></tr>`).join('')}</tbody></table></div><div class="actions">${c.portal_url?`<a class="btn" href="${esc(c.portal_url)}" target="_blank" rel="noopener">Open ${esc(c.vendor_code)} Portal</a>`:''}${can('submit_orders')&&c.status==='ready_to_submit'?`<button class="btn primary" data-review="${c.id}">Review / Queue Desktop</button>`:''}${can('parts')?`<button class="btn" data-orderstatus="${c.id}" data-current="${esc(c.status)}">Update Order Status</button>`:''}${['ordered','partially_shipped','shipped','backordered'].includes(c.status)?`<button class="btn" data-receive="${c.id}">Mark Received</button>`:''}</div>${c.order_reference||c.tracking_number||c.eta_text?`<div class="muted" style="margin-top:8px">Order: ${esc(c.order_reference||c.external_order_id||'—')} • Tracking: ${esc(c.tracking_number||'—')} • ETA: ${esc(c.eta_text||'—')}</div>`:''}</div>`).join('')||'<div class="empty">No procurement carts yet. Build carts from a work order.</div>'}</div>`;
  el('#buildAll').onclick=async()=>{const r=await api('/api/procurement/build-all',{method:'POST',body:'{}'});const missing=r.results.reduce((n,x)=>n+(x.missing?.length||0),0);alert(`Supplier carts rebuilt. ${missing} part requirement(s) still need a supplier match.`);await procurement()};
  el('#refreshSuppliers').onclick=async()=>{const r=await api('/api/procurement/refresh-suppliers',{method:'POST',body:'{}'});const configured=r.results.some(x=>x.status!=='not_configured');alert(configured?'Supplier availability refresh completed.':'Supplier lookup connector is not configured yet. Manual supplier offers and learned mappings remain available.');await procurement()};
  el('#refreshOrders').onclick=async()=>{const r=await api('/api/procurement/refresh-status',{method:'POST',body:'{}'});alert(r.status==='not_configured'?'Vendor status connector is not configured yet. You can still update tracking manually.':`Updated ${r.updated||0} order(s).`);await procurement()};
  document.querySelectorAll('[data-source]').forEach(b=>b.onclick=async()=>{const partId=b.dataset.source,vendor=d.vendors.find(v=>v.enabled);const vendorName=prompt('Vendor code: WSM, PU, TMS, or BRP',vendor?.code||'PU');if(!vendorName)return;const v=d.vendors.find(x=>x.code.toLowerCase()===vendorName.toLowerCase());if(!v)return alert('Vendor not found');const sku=prompt('Supplier SKU / part number','')||'',qty=prompt('Available quantity','1')||'0',cost=prompt('Your unit cost','0')||'0',eta=prompt('ETA / availability note','In stock')||'';await api(`/api/parts/${partId}/offers`,{method:'POST',body:JSON.stringify({vendorId:v.id,vendorSku:sku,availableQty:Number(qty),unitCost:Number(cost),eta})});await procurement()});
  document.querySelectorAll('[data-review]').forEach(x=>x.onclick=()=>reviewCart(x.dataset.review));
  document.querySelectorAll('[data-submit]').forEach(b=>b.onclick=async()=>{if(!confirm(b.dataset.wait==='true'?'This cart is below the supplier threshold. Force submission anyway?':'Submit this supplier cart now?'))return;const r=await api(`/api/procurement/carts/${b.dataset.submit}/submit`,{method:'POST',body:JSON.stringify({force:b.dataset.wait==='true'})});if(r.status==='manual_action_required')alert('Cart is ready, but live vendor ordering is not connected yet. The supplier portal and exact line list are preserved for manual checkout.');else alert(`Order status: ${r.status}`);await procurement()});
  document.querySelectorAll('[data-orderstatus]').forEach(b=>b.onclick=async()=>{const status=prompt('Status: ordered, backordered, partially_shipped, shipped, received, cancelled',b.dataset.current||'ordered');if(!status)return;const orderReference=prompt('Supplier order / confirmation number (optional)','')||'';const trackingNumber=prompt('Tracking number (optional)','')||'';const eta=prompt('ETA / status note (optional)','')||'';await api(`/api/procurement/carts/${b.dataset.orderstatus}`,{method:'PATCH',body:JSON.stringify({status,order_reference:orderReference,tracking_number:trackingNumber,eta_text:eta})});await procurement()});
  document.querySelectorAll('[data-receive]').forEach(b=>b.onclick=async()=>{if(!confirm('Mark all lines in this order received?'))return;await api(`/api/procurement/carts/${b.dataset.receive}`,{method:'PATCH',body:JSON.stringify({status:'received'})});await procurement()});
}
async function employees(){const d=await api('/api/users');current='employees';navActive();el('#view').innerHTML=`<div class="page-title"><div><h1>Employees & Access</h1><p class="muted">Each employee gets their own audit trail. PIN login is useful on a shared shop tablet; password remains available.</p></div><button class="btn primary" id="addEmployee">Add Employee</button></div><div class="card"><div class="line-table"><table><thead><tr><th>Name</th><th>Username</th><th>Role</th><th>Status</th><th>Last login</th></tr></thead><tbody>${d.users.map(u=>`<tr><td><strong>${esc(u.displayName)}</strong></td><td>${esc(u.username)}</td><td>${esc(u.role)}</td><td>${u.active?'Active':'Disabled'}</td><td>${esc(u.lastLoginAt||'Never')}</td></tr>`).join('')}</tbody></table></div></div><div class="card section"><h2>Role design</h2><div class="role-grid"><div><strong>Technician</strong><p>Assigned jobs, workflow changes, notes, photos, customer updates.</p></div><div><strong>Service Writer</strong><p>Everything customer-facing, approvals, ready/pickup, parts prep.</p></div><div><strong>Parts</strong><p>Supplier sourcing, carts, ordering status, receiving.</p></div><div><strong>Manager / Owner</strong><p>Full dashboard, employee access and purchasing controls.</p></div></div></div>`;el('#addEmployee').onclick=async()=>{const displayName=prompt('Employee name');if(!displayName)return;const username=prompt('Username',displayName.toLowerCase().replace(/[^a-z0-9]+/g,'.'));if(!username)return;const role=prompt('Role: technician, service_writer, parts, manager, viewer','technician');if(!role)return;const password=prompt('Temporary password (8+ characters)');if(!password)return;const pin=prompt('Optional 4-8 digit shop PIN','');try{await api('/api/users',{method:'POST',body:JSON.stringify({displayName,username,role,password,pin})});await employees()}catch(e){alert(e.message)}}}
async function boot(){const r=await api('/api/me');if(!r.user)return renderLogin();me=r;stages=r.stages;perms=new Set(r.permissions||[]);shell();const deep=new URLSearchParams(location.search).get('view');go(can('edit_job')&&['customers','vehicles','newwo','payments','hardware'].includes(deep)?deep:r.user.role==='technician'?'mywork':r.user.role==='parts'?'procurement':'dashboard')}
