  el('#view').innerHTML=`<button class="btn" id="backCustomers">← Customers</button><h1>${esc(c.name)}</h1><div class="grid two"><section class="card"><h2>Edit Customer</h2><form id="customerEdit">${field('Name','name',c.name)}${field('Phone','phone',c.phone)}${field('Email','email',c.email)}${addressForm(c)}<label class="field">Notes<textarea name="notes">${esc(c.notes)}</textarea></label><button class="btn primary">Save Changes</button></form></section><section class="card"><h2>Units / Vehicles</h2>${c.vehicles.map(v=>`<button class="directory-row" data-unit="${v.id}">${esc([v.year,v.make,v.model].filter(Boolean).join(' '))} <span>${esc(v.vin||v.hin||v.category)}</span></button>`).join('')||'<p class="muted">No units yet.</p>'}<button class="btn primary" id="addUnit">+ Add Vehicle</button><button class="btn" id="customerNewWO">+ Work Order</button></section></div><section class="card section"><h2>Work Order History</h2>${c.workOrders.map(w=>`<button class="directory-row" data-job="${w.id}">WO ${esc(w.ref_number)} • ${esc(w.stage)} • ${money(w.estimate_total)}</button>`).join('')||'No work orders yet'}</section>`;
